import sqlite3,json,pathlib,re
c=json.loads(pathlib.Path('content/ap/written-drafts/2024/author-spring-1-6/ap-r06h-pm6.json').read_text());blocks=re.findall(r'```sql\n(.*?)\n```',c['body'],re.S)
con=sqlite3.connect(':memory:');con.executescript('''CREATE TABLE 国民の祝日(祝日 TEXT,祝日名 TEXT);CREATE TABLE 会社記念日(会社番号 TEXT,会社記念日 TEXT,会社記念日名 TEXT);CREATE TABLE 従業員(会社番号 TEXT,従業員番号 INTEGER,従業員氏名 TEXT,部署番号 INTEGER);CREATE TABLE 部署(会社番号 TEXT,部署番号 INTEGER,部署名 TEXT,管理者番号 INTEGER);''')
con.executemany('INSERT INTO 国民の祝日 VALUES(?,?)',[('2024-04-01','開始'),('2025-03-31','終了'),('2025-04-01','範囲外')]);con.executemany('INSERT INTO 会社記念日 VALUES(?,?,?)',[('A','2024-09-01','A創立'),('B','2024-06-01','他社')]);con.executemany('INSERT INTO 部署 VALUES(?,?,?,?)',[('A',10,'部10',1),('A',20,'部20',1),('A',30,'部30',2),('B',10,'他社部',1)]);con.executemany('INSERT INTO 従業員 VALUES(?,?,?,?)',[('A',5,'五',20),('A',2,'二',10),('A',3,'三',10),('A',6,'六',30),('B',2,'他社二',10)])
first=blocks[0].replace('［b］','BETWEEN :年度開始日 AND :年度終了日').replace('［c］','ORDER BY');holidays=con.execute(first,{'会社番号':'A','年度開始日':'2024-04-01','年度終了日':'2025-03-31'}).fetchall();assert holidays==[('2024-04-01','開始'),('2024-09-01','A創立'),('2025-03-31','終了')]
second=blocks[1].replace('［d］','EMP.部署番号 = DEP.部署番号').replace('［c］','ORDER BY');employees=con.execute(second,{'会社番号':'A','管理者番号':1}).fetchall();assert employees==[(10,'部10',2,'二'),(10,'部10',3,'三'),(20,'部20',5,'五')]
# SQLite persistent cross-database views differ from exam schemas: execute TEMP projection across attached schema to validate reference rather than claim PostgreSQL syntax execution.
con.execute("ATTACH DATABASE ':memory:' AS PUB");con.executescript('CREATE TABLE PUB.国民の祝日(祝日 TEXT,祝日名 TEXT);INSERT INTO PUB.国民の祝日 VALUES("2024-04-01","開始");CREATE TEMP VIEW 国民の祝日投影(祝日,祝日名) AS SELECT 祝日,祝日名 FROM PUB.国民の祝日;');assert con.execute('SELECT * FROM 国民の祝日投影').fetchall()==[('2024-04-01','開始')]
result={'method':'作者原文SQLから公式空欄を埋め独立fixtureで実行。期首期末を含み他年度/他社を除外、2部署を管理する同一管理者の従業員を所属部署で結合し部署/従業員昇順をassert。','holidays':holidays,'employees':employees,'crossSchemaView':'公式C001.国民の祝日/PUB.国民の祝日は原図・公式と照合。SQLiteは同一DB内SQLスキーマとは異なるのでTEMP VIEWによる別attached DB参照の投影結果のみ検証。SQL標準スキーマ構文をSQLiteで実行したとは扱わない。'}
pathlib.Path(__file__).with_suffix('.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print('SQL assertions PASS')
